def transform(grid):
    out = [row[:] for row in grid]
    rows = [r for r in range(len(grid)) if 4 in grid[r]]
    if not rows:
        return out

    top, bottom = min(rows), max(rows)
    for r in range(len(out)):
        for c in range(len(out[0])):
            if out[r][c] == 6:
                out[r][c] = 0

    for i in range(bottom - top + 1):
        target = bottom + 1 + i
        source = bottom - i
        if target < len(out):
            for c, value in enumerate(grid[source]):
                if value == 4:
                    out[target][c] = 4
    return out
